@-moz-document domain("nitrotype.com") {
/* === General Body and Background Styles === */
    body {
        background: none; /* Removes any default background */
    }

    html {
        /* Sets a fixed background image with a fallback color */
        background: fixed url("https://i.ibb.co/XPyZ7gT/Rwwwwoblox-Player-Beta-Sj-U3-CI1-VQZ.png"), #001d45;
        background-size: 100%; /* Stretches the background image to cover the entire element */
    }

    .bg--gradient {
        background: fixed; /* Fixes the background, preventing it from scrolling */
    }

    /* === Profile Background Styles === */
    .theme--pDefault .profile-bg {
        /* Sets a background image and a linear gradient for the profile background */
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat, linear-gradient(0deg, #2d2e2e 60%, #ffffff 100%);
        color: #d3d3d3; /* Sets the text color */
        background-size: 110%; /* Slightly enlarges the background image */
        opacity: 0.1 /* Sets the opacity of the background */
    }


    .theme--pDefault .profile-bgHead {
        /* Sets a background image and a linear gradient for the profile header */
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat, linear-gradient(0deg, #2d2e2e 10%, #ffffff 100%);
        background-size: 110% /* Slightly enlarges the background image */
    }


    .theme--pDefault.is-gold .profile-bg {
        /* Sets a background image and a linear gradient for gold profile backgrounds */
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat, linear-gradient(0deg, #2d2e2e 10%, #ffffff 100%);
        background-size: 110% /* Slightly enlarges the background image */
    }

    /* === Season 28 Styles === */
    .structure.theme--season28 {
        background-image: none; /* Removes the background image for season 28 */
    }


    /* === Card Styles === */
    .card--a {
        background-color: #fff0; /* Sets a transparent background color */
        color: #ffffff; /* Sets the text color to white */
    }


    .card--shadow-l {
        box-shadow: none; /* Removes the box shadow */
    }

    /* === Profile Level Number Styles === */
    .theme--pDefault .profile-levelNum {
        color: #ffffff; /* Sets the text color to white */
        text-shadow: 0 2px 2px rgba(2, 2, 2, 0.25); /* Adds a text shadow */
    }

    /* === News Styles === */
    .news--solo .news-body p {
        color: #ffffff; /* Sets the text color to white */
        line-height: 1.8; /* Increases the line height for readability */
    }

    .news-teaser {
        color: #ffffff; /* Sets the text color to white */
        margin-bottom: 40px; /* Adds margin below the news teaser */
    }

    /* === Card Styles (repeated - consider consolidating) === */
    .card--a {
        color: #ffffff; /* Sets the text color to white */
        background: transparent; /* Sets a transparent background */
    }

    .card--shadow-l {
        box-shadow: none; /* Removes the box shadow */
    }

    /* === Button Styles === */
    .btn--inky {
        color: #fff; /* Sets the text color to white */
    }

    /* === Card Styles === */
    .card--b {
        color: #fff; /* Sets the text color to white */
    }

    /* === Profile Body Styles === */
    .theme--pDefault .profile-body {
        color: #ffffff; /* Sets the text color to white */
    }

    /* === Card Styles === */
    .card--grit {
        background: none; /* Removes the background */
    }

    /* === Dashboard Copy Container Styles === */
    .dash-copyContainer {
        background: #1d1e23; /* Sets a dark background color */
        box-shadow: 0 1px 157px 10px rgba(0, 0, 0, 0.78); /* Adds a large box shadow */
    }

    .dash-copy {
        color: #00cfff; /* Sets a light blue color */
        font-size: 28px; /* Sets the font size */
    }

    /* === Navigation Styles === */
    .nav {
        background: none; /* Removes the background */
        border: none; /* Removes the border */
    }


    .nav-list-item.is-current,
    .nav-link:hover {
        /* Styles for the current navigation item and hover state */
        background: linear-gradient(to bottom, #00bbe5, #00cfff)!important; /* Sets a linear gradient background */
        height: 90%; /* Adjusts the height */
        border-radius: 5px; /* Adds rounded corners */
    }


    .nav-list-item.is-current {
        /* Styles for the currently selected navigation item */
        border-top: 1px solid #00cfff; /* Adds a top border */
        border-right: 1px solid #00cfff; /* Adds a right border */
        border-bottom: 1px solid #00cfff; /* Adds a bottom border */
        border-left: 1px solid #00cfff; /* Adds a left border */
        border-radius: 5px; /* Adds rounded corners */
    }

    /* === Ad Styles (hiding ads) === */
    .structure-ad {
        display: none; /* Hides the ad structure */
    }


    .ad {
        display: none; /* Hides ads */
        position: relative;
        margin-right: auto;
        margin-left: auto;
        text-align: center;
    }


    .ad--sq {
        display: none; /* Hides square ads */
        width: 336px;
        height: 280px;
        background: #f2f2f2;
    }


    .ad--ldrbrd {
        display: none; /* Hides leaderboard ads */
        width: 728px;
        height: 90px;
        background: #f2f2f2;
    }


    .ad--ldrbrd_l {
        display: none; /* Hides large leaderboard ads */
        width: 970px;
        height: 90px;
    }


    .ad--fixed {
        display: none; /* Hides fixed position ads */
        position: fixed;
        top: 30px;
    }


    .theme--pDefault .profile-ad {
        display: none; /* Hides profile ads */
    }

    /* === Footer Styles (hiding footer) === */
    .footer {
        display: none; /* Hides the footer */
    }

    /* === Season Teaser Styles (hiding teaser) === */
    .seasonTeaser {
        display: none; /* Hides the season teaser */
    }

    /* === Dropdown Styles (hiding dropdown) === */
    .dropdown {
        display: none; /* Hides the dropdown */
    }

    /* === Gold Teaser Styles (hiding gold teaser) === */
    .goldTeaser {
        display: none; /* Hides the gold teaser */
    }

    /* === Garage Spot Styles === */
    .garage-spot::before {
        /* Sets a linear gradient background for the garage spot */
        background: linear-gradient(to bottom, #00a7cd, #00cfff)!important;
    }

    /* === Button Styles === */
    .btn--primary,
    .btn--primary:hover,
    .btn--primary:focus {
        background: #00cfff; /* Sets the background color to light blue */
    }

    /* === Notification Styles === */
    .notify {
        background: #00cfff; /* Sets the background color to light blue */
    }

    .notify::before {
        background: #00cfff; /* Sets the background color to light blue */
    }

    /* === Season Progress Widget Styles === */
    .season-progress-widget--level-progress-bar {
        background: #00cfff; /* Sets the background color to light blue */
    }

    .season-progress-widget--current-level--number {
        color: #97ebff; /* Sets a lighter blue color */
    }

    .season-reward-mini-preview--label {
        background-color: rgba(255, 255, 255, 0); /* Sets a transparent background */
    }

    /* === Season Card Styles === */
    .card--season {
        position: relative;
        color: #d3d3d3;
        background: none;
        background-size: 110%;
    }


    .card--season::before {
        /* Adds a pseudo-element for background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat, linear-gradient(0deg, #2d2e2e 60%, #ffffff 100%);
        opacity: 0.1;
        z-index: -1;
    }

    /* === Gold Link Styles (hiding link) === */
    .link--gold {
        display: none; /* Hides the gold link */
    }


    /* === Shop Page Styles (hiding elements) === */
    .page-shop--dealership-option.cash_shop {
        display: none; /* Hides the cash shop option */
    }

    .page-shop--dealership-option.merch_shop {
        display: none; /* Hides the merch shop option */
    }

    .page-shop--owned::before {
        background: #00cfff; /* Sets the background color to light blue */
    }

    /* === Tertiary Button Styles === */
    .btn--tertiary {
        background: #00cfff; /* Sets the background color to light blue */
    }

    .btn--tertiary:hover {
        background: #00cfff; /* Sets the background color to light blue on hover */
    }

    /* === Dealership Option Styles === */
    .page-shop--dealership-option {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .page-shop--dealership-option::before {
        /* Adds a pseudo-element for background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat, linear-gradient(0deg, #2d2e2e 60%, #ffffff 100%);
        opacity: 0.2;
        z-index: -1;
    }

    .page-shop--dealership-option.is-selected {
        background-color: rgba(0, 128, 255, 0);
    }


    .page-shop--dealership-option.is-selected::before {
        /* Adds a pseudo-element for selected state background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 128, 255, 0.2);
        opacity: 0.8;
        z-index: -1;
    }

    .page-shop--dealership-option:hover::before {
        opacity: 0.6;
    }


    .page-shop--dealership-option:hover {
        background-color: rgba(0, 128, 255, 0.2);
    }

    /* === Tab Styles === */
    .tabs--a .tab {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .tabs--a .tab::before {
        /* Adds a pseudo-element for background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat, linear-gradient(0deg, #2d2e2e 60%, #ffffff 100%);
        opacity: 0.4;
        z-index: -1;
    }


    .tabs--a .tab:hover::before {
        opacity: 0.6;
    }


    .tabs--a .tab:hover {
        background-color: rgba(0, 207, 255, 0.5);
    }

    .tabs--a .tab.is-active {
        background-color: rgba(0, 128, 255, 0);
    }


    .tabs--a .tab.is-active::before {
        /* Adds a pseudo-element for active state background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 128, 255, 0.2);
        z-index: -1;
    }

    .tabs--a .tab:not(.is-disabled):not(.is-active):hover {
        background: none !important;
        color: inherit !important;
    }

    /* === Card Styles === */
    .card--d {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .card--d::before {
        /* Adds a pseudo-element for background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
    }

    /* === Table Styles === */
    .table.table--selectable.table--striped.table--friends {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .table.table--selectable.table--striped.table--friends::before {
        /* Adds a pseudo-element for background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
        transition: opacity 0.3s ease;
    }


    .table.table--selectable.table--striped.table--friends:hover::before {
        opacity: 1;
    }


    .table.table--selectable.table--striped.table--friends:hover {
        background-color: rgba(0, 0, 0, 0.1);
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell::before,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell::before {
        /* Adds a pseudo-element for hover state background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover::before,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover::before {
        opacity: 1;
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover {
        background-color: rgba(0, 0, 0, 0.1);
    }


    /* Forcefully remove background from striped row cells and add hover effect */
    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) .table-cell {
        position: relative;
        background: none !important; /* Force removal */
        overflow: hidden;
    }


    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) .table-cell::before {
        /* Adds a pseudo-element for striped row background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: none;
        opacity: 0;
        z-index: -1;
    }


    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) .table-cell:hover {
        background-color: rgba(0, 0, 0, 0.1) !important; /* Force hover color */
    }


    /* Forcefully remove background from striped rows */
    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) {
        background: none !important;
    }

    .table-head .table-cell {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .table-head .table-cell::before {
        /* Adds a pseudo-element for table header background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
    }


    .table-head .table-cell:hover::before {
        opacity: 1;
    }


    .table-head .table-cell:hover {
        background-color: rgba(0, 0, 0, 0.1);
    }

    /* === Switch Styles === */
    .switch.checked .switch-selection,
    .switch-input:checked + .switch-label--off ~ .switch-selection {
        background: #00cfff;
    }

    .switch-selection {
        background: #00c33f;
    }

    /* === League Standings Table Styles === */
    .table.table--selectable.table--striped.leagues--standings.for-player {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .table.table--selectable.table--striped.leagues--standings.for-player::before {
        /* Adds a pseudo-element for league standings table background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
        transition: opacity 0.3s ease;
    }


    .table.table--selectable.table--striped.leagues--standings.for-player:hover::before {
        opacity: 1;
    }


    .table.table--selectable.table--striped.leagues--standings.for-player:hover {
        background-color: rgba(0, 0, 0, 0.1);
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell::before,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell::before {
        /* Adds a pseudo-element for hover state background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover::before,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover::before {
        opacity: 1;
    }


    .table--selectable .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover,
    .table--selectable.table--striped .table-body .table-row:not(.is-accepted):not(.is-ignored):hover .table-cell:hover {
        background-color: rgba(0, 0, 0, 0.1);
    }


    /* Forcefully remove background from striped row cells and add hover effect */
    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) .table-cell {
        position: relative;
        background: none !important; /* Force removal */
        overflow: hidden;
    }


    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) .table-cell::before {
        /* Adds a pseudo-element for striped row background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: none;
        opacity: 0;
        z-index: -1;
    }


    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) .table-cell:hover {
        background-color: rgba(0, 0, 0, 0.1) !important; /* Force hover color */
    }


    /* Forcefully remove background from striped rows */
    .table--striped .table-body .table-row:nth-child(2n + 1):not(.table-row--gold):not(.table-row--silver):not(.table-row--bronze) {
        background: none !important;
    }


    .table-head .table-cell {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .table-head .table-cell::before {
        /* Adds a pseudo-element for table header background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0.5;
        z-index: -1;
    }


    .table-head .table-cell:hover::before {
        opacity: 1;
    }


    .table-head .table-cell:hover {
        background-color: rgba(0, 0, 0, 0.1);
    }

    td.leagues--standings--experience {
        background: none;
    }

    th.leagues--standings--experience {
        background: none;
    }

    .table.table--selectable.table--striped.leagues--standings.for-team {
        background: none !important;
    }


    .table.table--selectable.table--striped.leagues--standings.for-team::before {
        background: none !important;
    }

    /* === Card Styles === */
    .card--e {
        background: none !important;
    }

    /* === Table Styles === */
    .table.table--striped {
        background: none !important;
    }

    /* === Achievement Styles === */
    .achievement {
        background: none !important;
    }

    /* === Progress Bar Styles === */
    .prog--c .prog-barFill {
        background: #00cfff;
    }

    /* === Button, Modal, and Friend Join Button Styles === */
    .btn,
    .modal--bundle-offer--purchase-option,
    .friends-list--friend-status--join-race-button {
        position: relative;
        background: none;
        overflow: hidden;
    }


    .btn::before,
    .modal--bundle-offer--purchase-option::before,
    .friends-list--friend-status--join-race-button::before {
        /* Adds a pseudo-element for button background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: url("https://i.ibb.co/fYcLHRRk/sssdsd.png") top left repeat,
        linear-gradient(0deg, #2d2e2e 60%, #ffffff 100%);
        opacity: 0.2;
        z-index: -1;
    }


    .btn.is-selected,
    .modal--bundle-offer--purchase-option.is-selected,
    .friends-list--friend-status--join-race-button.is-selected {
        background-color: rgba(0, 128, 255, 0);
    }


    .btn.is-selected::before,
    .modal--bundle-offer--purchase-option.is-selected::before,
    .friends-list--friend-status--join-race-button.is-selected::before {
        /* Adds a pseudo-element for selected state background overlay */
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 128, 255, 0.2);
        opacity: 0.8;
        z-index: -1;
    }


    .btn:hover::before,
    .modal--bundle-offer--purchase-option:hover::before,
    .friends-list--friend-status--join-race-button:hover::before {
        opacity: 0.6;
    }


    .btn:hover,
    .modal--bundle-offer--purchase-option:hover,
    .friends-list--friend-status--join-race-button:hover {
        background-color: rgba(0, 128, 255, 0.2);
    }

    /* === Race Chat Styles === */
    .raceChat-pickerContainer {
        background: none;
    }

    .raceChat-picker.is-toggled .raceChat-pickerToggle {
        background: none;
    }

    .raceChat-pickerToggle {
        background: none;
    }

    .raceChat-picker.is-toggled .raceChat-pickerToggle:hover {
        background: rgba(0, 0, 0, 0.1);
    }


    @keyframes raceChat-bubbleIn {}


    @keyframes raceChat-bubbleOut {}


    @keyframes raceChat-togglePulse {}


    @keyframes raceChat-toggleEnter {}


    .raceChat-toggle {
        background: rgba(0,
        0,
        0,
        0.1) !important;
    }


    .raceChat-picker.is-toggled .raceChat-pickerToggle:hover {
        background: rgba(0,
        0,
        0,
        0.1) !important;
    }

    .raceChat-pickerToggle::before {
        background: none;
    }

    /* === Dashboard Word Styles === */
    .dash-word {
        text-align: center;
        text-decoration: underline;
        font-size: 32px;
        font-family: monospace;
        letter-spacing: 5px;
        background: #00cfff;
        background-repeat: repeat;
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
        animation: animated_text 6s ease-in-out infinite;
        background-size: 400% 100%;
    }

    @keyframes animated_text {
        0%,
        100% {
            background-position: 0 0;
        }


        50% {
            background-position: 100% 0;
        }

    }

    .dash-copyContainer {
        background: #1d1e23;
        box-shadow: 0 1px 157px 10px rgba(0, 0, 0, 0.78);
    }

    .dash-letter.is-correct.is-typed {
        opacity: 0;
    }
}
